SET @rbac_safe := @permission_collision=0 AND @permission_duplicates=0 AND @off_matrix=0 AND (SELECT COUNT(*)=5 FROM `alrowad_uni_rust`.`roles` WHERE role_code IN ('student','registration_officer','exam_officer','dean','vice_president_scientific') AND is_active=1) AND (SELECT COUNT(*)=1 FROM `alrowad_uni_rust`.`system_modules` WHERE module_code='exams' AND is_active=1);
SET @rbac_exact := (SELECT COUNT(DISTINCT CONCAT(r.role_code,':',p.permission_code))=7 FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE m.module_code='exams' AND m.is_active=1 AND p.is_active=1 AND ((p.permission_code='supplementary_exams.registrations.self' AND r.role_code='student') OR (p.permission_code='supplementary_exams.registrations.view' AND r.role_code IN ('registration_officer','exam_officer','dean','vice_president_scientific')) OR (p.permission_code IN ('supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND r.role_code='registration_officer')));
SET @invalid_rows:=1;SET @orphan_events:=1;SET @duplicate_identity:=1;SET @duplicate_current:=1;SET @summer_violations:=1;
SET @sql:=IF(@reg_state='COMPATIBLE','SELECT COUNT(*) INTO @invalid_rows FROM `alrowad_uni_rust`.`supplementary_exam_registrations` r LEFT JOIN `alrowad_uni_rust`.`student_course_registrations` scr ON scr.student_course_registration_id=r.student_course_registration_id LEFT JOIN `alrowad_uni_rust`.`supplementary_exam_offering_sources` src ON src.supplementary_exam_offering_id=r.supplementary_exam_offering_id AND src.course_offering_id=scr.course_offering_id WHERE r.status NOT IN (''registered'',''cancelled'') OR (r.status=''registered'' AND (r.current_slot IS NULL OR r.current_slot<>1 OR r.cancelled_by_user_id IS NOT NULL OR r.cancelled_at IS NOT NULL)) OR (r.status=''cancelled'' AND (r.current_slot IS NOT NULL OR r.cancelled_by_user_id IS NULL OR r.cancelled_at IS NULL)) OR r.eligibility_reason NOT IN (''failed_theoretical'',''voluntarily_deferred_theoretical'') OR r.registration_channel NOT IN (''student_self'',''student_affairs'') OR scr.student_course_registration_id IS NULL OR scr.student_id<>r.student_id OR src.supplementary_exam_offering_source_id IS NULL','SET @invalid_rows=1');PREPARE v FROM @sql;EXECUTE v;DEALLOCATE PREPARE v;
SET @sql:=IF(@event_state='COMPATIBLE','SELECT COUNT(*) INTO @orphan_events FROM `alrowad_uni_rust`.`supplementary_exam_registration_events` e LEFT JOIN `alrowad_uni_rust`.`supplementary_exam_registrations` r ON r.supplementary_exam_registration_id=e.supplementary_exam_registration_id LEFT JOIN `alrowad_uni_rust`.`users` u ON u.user_id=e.actor_user_id WHERE r.supplementary_exam_registration_id IS NULL OR u.user_id IS NULL','SET @orphan_events=1');PREPARE v FROM @sql;EXECUTE v;DEALLOCATE PREPARE v;
SET @sql:=IF(@reg_state='COMPATIBLE','SELECT COUNT(*) INTO @duplicate_identity FROM (SELECT 1 FROM `alrowad_uni_rust`.`supplementary_exam_registrations` GROUP BY supplementary_exam_offering_id,student_course_registration_id HAVING COUNT(*)>1) d','SET @duplicate_identity=1');PREPARE v FROM @sql;EXECUTE v;DEALLOCATE PREPARE v;
SET @sql:=IF(@reg_state='COMPATIBLE','SELECT COUNT(*) INTO @duplicate_current FROM (SELECT 1 FROM `alrowad_uni_rust`.`supplementary_exam_registrations` WHERE status=''registered'' AND current_slot=1 GROUP BY supplementary_exam_offering_id,student_id HAVING COUNT(*)>1) d','SET @duplicate_current=1');PREPARE v FROM @sql;EXECUTE v;DEALLOCATE PREPARE v;
SET @sql:=IF(@reg_state='COMPATIBLE','SELECT COUNT(*) INTO @summer_violations FROM (SELECT 1 FROM `alrowad_uni_rust`.`supplementary_exam_registrations` r JOIN `alrowad_uni_rust`.`supplementary_exam_offerings` o ON o.supplementary_exam_offering_id=r.supplementary_exam_offering_id JOIN `alrowad_uni_rust`.`supplementary_exam_periods` p ON p.supplementary_exam_period_id=o.supplementary_exam_period_id JOIN `alrowad_uni_rust`.`semesters` s ON s.semester_id=p.semester_id WHERE s.semester_order=3 AND r.status=''registered'' AND r.current_slot=1 GROUP BY p.supplementary_exam_period_id,r.student_id HAVING COUNT(*)>3) excessive','SET @summer_violations=1');PREPARE v FROM @sql;EXECUTE v;DEALLOCATE PREPARE v;
SET @verify_ok := @phase3_ready AND @period_lifecycle_width_ready AND @reg_state='COMPATIBLE' AND @event_state='COMPATIBLE' AND @rbac_safe AND @rbac_exact AND @invalid_rows=0 AND @orphan_events=0 AND @duplicate_identity=0 AND @duplicate_current=0 AND @summer_violations=0;
SELECT 'OVERALL' AS report_section,IF(@verify_ok,'PASS','FAIL') AS result,IF(NOT @phase3_ready,'PHASE3_NOT_DEPLOYED',IF(NOT @period_lifecycle_width_ready,'PERIOD_LIFECYCLE_SCHEMA_TOO_NARROW',IF(@reg_state<>'COMPATIBLE' OR @event_state<>'COMPATIBLE','PHASE4_SCHEMA_INVALID',IF(NOT @rbac_safe OR NOT @rbac_exact,'RBAC_INVALID','DATA_INVALID')))) AS blocker_code,@reg_state AS registrations_state,@event_state AS events_state,@invalid_rows AS invalid_rows,@duplicate_identity AS duplicate_identity,@duplicate_current AS duplicate_current,@summer_violations AS summer_violations;
